#!/usr/bin/env python3
"""Standard-library projection of saved research evidence; never runs the solver."""
import hashlib,json,pathlib
HERE=pathlib.Path(__file__).resolve().parent;ROOT=HERE.parents[1];DATA=ROOT/'examples/plate_fin_experiment'
sha=lambda p:hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
load=lambda p:json.loads(p.read_text())
def main():
 c=load(DATA/'experimental_comparison.json');a=load(DATA/'applicability_audit.json');v=load(DATA/'verification.json');src=load(HERE/'inputs/figure8_markers.json');rows=[];bad=[]
 display=load(DATA/'display_fields.json');wi=c['geometry']['interior_gap_m'];ws=c['geometry']['side_gap_m']
 display['channel_domains']=[{'channel_index_from_side':0,'role':'side_clearance_full_channel','physical_full_channel_width_m':ws,'modeled_width_fraction':1.,'modeled_width_m':ws,'floor_boundary':'adiabatic duct outside base','left_boundary':'adiabatic duct sidewall','right_boundary':'outer fin'},{'channel_index_from_side':1,'role':'interior_full_channel','physical_full_channel_width_m':wi,'modeled_width_fraction':1.,'modeled_width_m':wi,'floor_boundary':'isothermal heat-sink base','left_boundary':'fin','right_boundary':'fin'},{'channel_index_from_side':8,'role':'central_interior_half_channel','physical_full_channel_width_m':wi,'modeled_width_fraction':.5,'modeled_width_m':wi/2,'floor_boundary':'isothermal heat-sink base','left_boundary':'innermost modeled fin','right_boundary':'mirror symmetry plane; not a duct wall'}]
 display['coordinate_notice']='x and y are actual local cell-centre coordinates in mm. Channel8 occupies only half an interior gap; do not stretch its samples into a full channel. Channel index is counted inward from the duct side in the mirrored half-array.'
 display['fin_domains']=[{'fin_index_from_side':0,'role':'outermost fin adjacent to side clearance'},{'fin_index_from_side':7,'role':'innermost modeled fin adjacent to central half-channel'}]
 (DATA/'display_fields.json').write_text(json.dumps(display,separators=(',',':'))+'\n')
 for marker,scope in zip(src['rows'],a['rows']):
  i=marker['marker_index']; predictions={}
  for profile in ['fd','plug']:
   r=next(r for r in c['results'] if r['marker_index']==i and r['profile']==profile)
   predictions[profile]={'G_W_K':r['prediction']['G_W_K'],'Rth_K_W':r['prediction']['Rth_K_W'],'relative_Rth_discrepancy':r['relative_Rth_discrepancy'],'relative_G_discrepancy':r['relative_G_discrepancy'],'side_channels_G_fraction':r['side_channels_G_fraction'],'naive_17_central_channels_relative_G_bias':r['naive_17_central_channels_relative_G_bias']}
  rows.append({'id':marker['marker_id'],'marker_index':i,'source_drawing_index':marker['drawing_index'],'observed':{'V_channel_inferred_m_s':marker['V_channel_inferred_m_s'],'Rth_K_W':marker['Rth_K_W'],'G_W_K':1/marker['Rth_K_W']},'scope':scope,'author_uncertainty_separate':dict(src['author_uncertainty_separate'],Rth_absolute_K_W=.012*marker['Rth_K_W']),'graphical_readout_allowance_separate':marker['conservative_graphical_half_symbol_envelope'],'predictions':predictions})
  p=predictions['fd'];bias=p['naive_17_central_channels_relative_G_bias'];Gbad=p['G_W_K']*(1+bias)
  bad.append({'marker_id':marker['marker_id'],'scope':scope['scope'],'V_m_s':marker['V_channel_inferred_m_s'],'correct_G_W_K':p['G_W_K'],'correct_Rth_K_W':p['Rth_K_W'],'incorrect_17_interior_G_W_K':Gbad,'incorrect_17_interior_Rth_K_W':1/Gbad,'relative_conductance_overstatement':bias,'incorrect_relative_Rth_discrepancy':1/(Gbad*marker['Rth_K_W'])-1,'correct_relative_Rth_discrepancy':p['relative_Rth_discrepancy']})
 counter={'schema_version':1,'study_id':'plate_fin_2024','label':'Boundary-ownership counterexample, intentionally incorrect shortcut','not_an_accepted_model':True,'definition':'Multiply the central interior-channel conductance by17 instead of retaining15 heated-floor interior channels and2 one-fin-face, adiabatic-floor side channels','physical_ownership':{'fins':16,'interior_channels':15,'side_channels':2,'interior_floor':'isothermal heat-sink base','side_floor':'adiabatic duct surface outside41.5mm base','side_channel_fin_faces':1,'interior_channel_fin_faces':2},'warning':'The shortcut adds heated area and masks disagreement. It is shown only as a counterexample, never as an alternate validation pass.','source_comparison_sha256':sha(DATA/'experimental_comparison.json'),'rows':bad}
 (DATA/'side_channel_counterexample.json').write_text(json.dumps(counter,indent=2)+'\n')
 report={'schema_version':1,'study_id':'plate_fin_2024','report_kind':'saved_conditional_experimental_comparison','live_computation':False,'mathematical_verification_pass':True,'physical_validation_pass':None,'aircraft_transfer_authorized':False,'source_pdf_required':False,'source_pdf_redistributed':False,'chronology':'Saved original comparison with a separate post-comparison packaging replay; original precomparison freeze is preserved byte-for-byte.','source':{'title':'Pires-Fonseca and Carrasco-Altemani,2024, Figure8 plate-fin series','doi':src['source_doi'],'url':'https://doi.org/'+src['source_doi'],'marker_count':12,'author_claimed_run_count':13,'missing_point_policy':src['missing_run_policy']},'source_conditioning':{'response':'Approximate vector-marker Rth=(Tb-Tin)/qcv; qcv is electrical power minus estimated losses, not raw temperatures','speed':'Nozzle flow divided equally among17 channels; reported V mapped to arithmetic interior-channel area','properties':'Source numerical air properties, not recovered per-run conditions; aluminum conductivity independently declared'},'primary_profile':'fd','model_forms':{'fd':'Prescribed fully developed rectangular laminar velocity','plug':'Prescribed plug transport, not a no-slip momentum solution'},'model_forms_are_confidence_bounds':False,'geometry':c['geometry'],'geometry_ownership':counter['physical_ownership'],'nominal_properties':c['nominal_properties'],'frozen_numerics':c['numerics'],'laminar_cutoff_Re':2300,'scope_counts':{'robustly_in_declared_laminar_scope':3,'nominally_laminar_boundary_uncertain':1,'nominally_outside_laminar_scope':8},'scope_screen_notice':a['method'],'rows':rows,'material_sensitivity':c['material_sensitivity_primary_fd_in_scope'],'reported_area_mapping_sensitivity':c['reported_area_mapping_sensitivity_primary_fd_in_scope'],'air_property_sensitivities':c['air_property_sensitivities_at_predeclared_10_m_s'],'sensitivity_notice':'Prespecified material/property/model-form cases, not fitted parameters or confidence intervals','verification_summary':{'original_mathematical_gate_count':len(v['gates']),'all_original_gates_pass':all(v['gates'].values()),'maximum_spatial_relative_G_difference':max(r['relative_48_to_64_spatial'] for r in v['refinement_comparisons']),'maximum_axial_relative_G_difference':max(r['relative_800_to_1600_axial'] for r in v['refinement_comparisons']),'maximum_refinement_energy_relative_imbalance':max(r['energy_relative_balance_max'] for r in v['new_runs']),'difference_notice':'Refinement differences are numerical-convergence evidence, not uncertainty bounds'},'omissions':['hydrodynamic entrance development','axial solid conduction','axial fluid conduction','turbulence','base spreading','contact resistance','duct heat loss','measured per-channel flow partition'],'limitations':c['limitations'],'artifact_paths':{'comparison':'examples/plate_fin_experiment/experimental_comparison.json','source_markers':'research/plate_fin/inputs/figure8_markers.json','counterexample':'examples/plate_fin_experiment/side_channel_counterexample.json','fields':'examples/plate_fin_experiment/display_fields.json','verification':'examples/plate_fin_experiment/verification.json','frozen_numerics':'examples/plate_fin_experiment/frozen_numerics.json','packaging_replay':'examples/plate_fin_experiment/packaging_replay.json'},'provenance':{'solver_sha256':sha(HERE/'conjugate_fin.py'),'original_comparison_sha256':sha(HERE/'original_freeze/comparison.json'),'original_precomparison_freeze_sha256':sha(HERE/'original_freeze/frozen_numerics.json'),'source_marker_transcription_sha256':sha(HERE/'inputs/figure8_markers.json'),'projection_script_sha256':sha(__file__)}}
 (DATA/'plate_fin_report.json').write_text(json.dumps(report,indent=2)+'\n')
 index={k:report[k] for k in ['schema_version','study_id','report_kind','live_computation','mathematical_verification_pass','physical_validation_pass','aircraft_transfer_authorized','source_pdf_required','source_pdf_redistributed','chronology','source','source_conditioning','scope_counts']}
 index.update({'report_path':'examples/plate_fin_experiment/plate_fin_report.json','stable_report_keys':['study_id','source_conditioning','geometry_ownership','nominal_properties','frozen_numerics','scope_counts','rows[].id','rows[].observed','rows[].scope.scope','rows[].author_uncertainty_separate','rows[].graphical_readout_allowance_separate','rows[].predictions.fd','rows[].predictions.plug','verification_summary','physical_validation_pass','aircraft_transfer_authorized'],'report_sha256':sha(DATA/'plate_fin_report.json'),'package_manifest_path':'examples/plate_fin_experiment/package_manifest.json','residual_display':'100 times relative_Rth_discrepancy is percent resistance difference; positive means higher predicted resistance and lower predicted conductance','field_display_contract':'Match channel_index_from_side to display_fields.channel_domains; channel8 is a half-channel with modeled_width_fraction0.5','display_warning':'Integrity checks and numerical equivalence are not experimental or aircraft validation.'})
 (DATA/'replay_index.json').write_text(json.dumps(index,indent=2)+'\n')
 print('Wrote stable saved-report projection and ownership counterexample')
if __name__=='__main__':main()
